PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS profile(id INTEGER PRIMARY KEY CHECK(id=1), name TEXT NOT NULL, consent INTEGER NOT NULL DEFAULT 0 CHECK(consent IN (0,1)));
INSERT OR IGNORE INTO profile VALUES(1,'Demo participant',0);
CREATE TABLE IF NOT EXISTS memories(id INTEGER PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL, approved INTEGER NOT NULL CHECK(approved IN (0,1)));
CREATE TABLE IF NOT EXISTS reminders(id INTEGER PRIMARY KEY, title TEXT NOT NULL, due_at TEXT NOT NULL, acknowledged INTEGER NOT NULL DEFAULT 0 CHECK(acknowledged IN (0,1)));
CREATE TABLE IF NOT EXISTS sessions(id INTEGER PRIMARY KEY, correct INTEGER NOT NULL, attempts INTEGER NOT NULL, hints INTEGER NOT NULL, paused INTEGER NOT NULL, level INTEGER NOT NULL, recommendation TEXT NOT NULL, next_level INTEGER NOT NULL, model_action TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
